-- Phase 7 Back Office: employee timecards and operational management\ncreate table if not exists public.staff_timecards (id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,staff_id uuid not null references public.staff(id) on delete cascade,clock_in timestamptz not null default now(),clock_out timestamptz,notes text,created_by uuid references auth.users(id),created_at timestamptz not null default now(),constraint staff_timecards_time_check check(clock_out is null or clock_out>=clock_in));\ncreate index if not exists staff_timecards_property_staff_time_idx on public.staff_timecards(property_id,staff_id,clock_in desc);\nalter table public.staff_timecards enable row level security;\ndrop policy if exists staff_timecards_select on public.staff_timecards;drop policy if exists staff_timecards_insert on public.staff_timecards;drop policy if exists staff_timecards_update on public.staff_timecards;\ncreate policy staff_timecards_select on public.staff_timecards for select to authenticated using(public.is_member_of_property(property_id));\ncreate policy staff_timecards_insert on public.staff_timecards for insert to authenticated with check(public.is_member_of_property(property_id));\ncreate policy staff_timecards_update on public.staff_timecards for update to authenticated using(public.is_member_of_property(property_id)) with check(public.is_member_of_property(property_id));\ncreate or replace function public.fn_clock_staff(p_property_id uuid,p_staff_id uuid,p_clock_out boolean default false,p_notes text default null) returns public.staff_timecards language plpgsql security invoker set search_path='' as $$ declare row public.staff_timecards; begin if not public.is_member_of_property(p_property_id) then raise exception 'Not allowed.';end if;if p_clock_out then update public.staff_timecards set clock_out=coalesce(clock_out,now()),notes=coalesce(p_notes,notes) where property_id=p_property_id and staff_id=p_staff_id and clock_out is null returning * into row;if row.id is null then raise exception 'No open timecard for this employee.';end if;else if exists(select 1 from public.staff_timecards where property_id=p_property_id and staff_id=p_staff_id and clock_out is null) then raise exception 'Employee already has an open timecard.';end if;insert into public.staff_timecards(property_id,staff_id,created_by,notes) values(p_property_id,p_staff_id,auth.uid(),p_notes) returning * into row;end if;return row;end $$;\ngrant execute on function public.fn_clock_staff(uuid,uuid,boolean,text) to authenticated;\nnotify pgrst,'reload schema';